"""Chapter 6 (the Workshop) Parts 1 to 3: play Learn lv1-lv5 + Check c6r1-c6r5 (levers), pl1-pl4 + Check c6r7-c6r11 (pulleys, wheels and ramps) and u1-u3 + Challenge y1-y3 + Check c6r12-c6r17 (mechanical advantage and work) with real clicks, as a Grade 7 student would.
Run after build.py:  python3 tests/play_c6.py     Screenshots: /tmp/fhq-shots/c6/"""
import json, pathlib, sys, os
sys.path.insert(0, os.path.dirname(__file__))
from fc_helper import finish_check
from playwright.sync_api import sync_playwright
F = pathlib.Path('dist/test.html').resolve().as_uri(); OUT = '/tmp/fhq-shots/c6/'; pathlib.Path(OUT).mkdir(parents=True, exist_ok=True)
fails = []
def chk(name, cond, extra=''):
    print(('PASS ' if cond else 'FAIL ') + name + (' ' + str(extra) if (extra and not cond) else ''))
    if not cond: fails.append(name)
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={'width': 1440, 'height': 1000}); errs = []
    pg.on('pageerror', lambda e: errs.append('ERR ' + str(e))); pg.on('console', lambda m: m.type == 'error' and errs.append(m.text))
    pg.goto(F); pg.wait_for_timeout(400); pg.fill('#whoName', 'Sam'); pg.click('#whoGo'); pg.evaluate("__fhq.dbSet('tourDone',true)")
    ev = lambda c: pg.evaluate("c=>__fhq.ev(c)", c)
    def cards():
        for _ in range(12):
            n = pg.locator('#chunk [data-cb=next]')
            if n.count() and n.is_visible(): n.click(); pg.wait_for_timeout(100)
            else: break
    def dock():
        if pg.locator('#qPop').is_hidden(): ev("qPlace('pop')"); pg.wait_for_timeout(150)
    def nxt():
        q = pg.locator('#qNext')
        if q.count() and q.is_visible(): q.click()
        else: pg.click('#gNext')
        pg.wait_for_timeout(250); m = pg.locator('#modal #contAnyway')
        if m.count() and m.is_visible(): m.click(); pg.wait_for_timeout(200)
    jclick = lambda sel: pg.evaluate('s=>document.querySelector(s).click()', sel)
    stepDone = lambda: ev("stepDone(CH.id, GI)")
    q = lambda qid: pg.locator(f'#qCard [data-q="{qid}"], #dataCard [data-q="{qid}"]')
    fbq = lambda qid: q(qid).locator('.fb').inner_text()
    def ptsq(qid): return q(qid).locator('.ptsb').first.inner_text().strip()
    def pull(secs=6):   # press the real button, then let the animation run
        jclick('#wsPull'); pg.wait_for_timeout(200); ev(f"(()=>{{for(let i=0;i<{int(secs/0.02)};i++)wsUpdate(0.02)}})()"); pg.wait_for_timeout(150)
    def setnum(sel, v): pg.fill(sel, str(v)); pg.press(sel, 'Enter'); pg.wait_for_timeout(120)
    def tkans(qid, v):
        pg.locator(f'#rail .tkans[data-qid={qid}] .tkin').fill(str(v)); pg.locator(f'#rail .tkans[data-qid={qid}] [data-chkq]').click(); pg.wait_for_timeout(150)
        return pg.locator(f'#rail .tkans[data-qid={qid}] .tkmsg').inner_text()
    def predict(i): pg.locator('#rail [data-pred]').nth(i).click(); pg.wait_for_timeout(150)
    # --- lesson mode: the Workshop board is driven with real pointer moves (Part 1) ---
    def bxy(x, y):
        pg.evaluate("window.scrollTo(0, document.querySelector('#cvScene').getBoundingClientRect().top + scrollY - 16)"); pg.wait_for_timeout(60)
        bb = pg.locator('#cvScene').bounding_box(); return bb['x'] + x * bb['width'] / 900, bb['y'] + y * bb['height'] / 430
    def bdrag(a, b2, steps=12):
        ax, ay = bxy(*a); bx, by = bxy(*b2); pg.mouse.move(ax, ay); pg.mouse.down()
        for i in range(1, steps + 1): pg.mouse.move(ax + (bx - ax) * i / steps, ay + (by - ay) * i / steps)
        pg.mouse.up(); pg.wait_for_timeout(120)
    def lgeo(): return json.loads(ev("JSON.stringify([lsLever(0,wsCalc()), lsGrab(lsLever(0,wsCalc()))])"))
    def lever_on():   # drag the lever from the tray under the rock
        pg.evaluate("window.scrollTo(0, document.querySelector('#cvScene').getBoundingClientRect().top + scrollY - 16)"); a = pg.locator('#lsTray [data-lsadd=lever]').bounding_box()
        pg.mouse.move(a['x'] + 20, a['y'] + 20); pg.mouse.down(); pg.mouse.move(*bxy(360, 300), steps=10); pg.mouse.up(); pg.wait_for_timeout(200)
    def arm_to(v):    # drag the fulcrum (or the rock, or your hand) to a distance, like a student
        G, g = lgeo(); bdrag((g['x'], g['y']), (g['x'] + (v - ev("WS.arm")) * 120, g['y']))
    def lever_menu():  # tap the bar, away from the part you drag
        G, g = lgeo(); x = G['b']['x'] - 40 if abs(G['b']['x'] - 40 - g['x']) > 60 else G['a']['x'] + 30; pgx, pgy = bxy(x, G['a']['y']); pg.mouse.click(pgx, pgy); pg.wait_for_timeout(150)

    def pick(qid, *vals, R=None):
        loc = R if R is not None else q(qid)
        for k, v in enumerate(vals): loc.locator('.pickin').nth(k).select_option(str(v))
        loc.locator('.qchk').click(); pg.wait_for_timeout(100)
    def mcq(qid, o): q(qid).locator(f'[data-o="{o}"]').first.click(); pg.wait_for_timeout(100)
    def finish(sid):
        chk(f'{sid}: step done', stepDone()); pg.screenshot(path=OUT + f'{sid}_done.png'); nxt()

    # ---------- the story opens the chapter: Smooshy's live call from inside the Gumdrop (spec section 9) ----------
    pg.evaluate("__fhq.dbSet('stamps',{})")
    ev("show('vHome')"); pg.wait_for_timeout(300); pg.screenshot(path=OUT + 'home.png', full_page=True)
    chk('home: the Workshop card opens Chapter 6', 'Save Captain Smooshy' in pg.locator('#workshopCard').inner_text() and pg.locator('#workshopCard [data-open=c6a]').count() == 1)
    chk('home: the card and title use the GASA story', 'Chapter 6 · The Workshop and Mission Control' in pg.locator('#workshopCard').text_content() and 'GASA Research and Development Centre' in pg.locator('.herosub').text_content() and 'plan his rescue at Mission Control' in pg.locator('#workshopCard').text_content())
    # the Mission Control building on the home map: its hit area is clickable, locked until Part 4 is done (teachers can always go in)
    def home_tap(id_):
        h = json.loads(ev("JSON.stringify(HOMEHIT.find(h=>h.id==='%s'))" % id_)); bb = pg.locator('#cvHome').bounding_box(); W = ev('HOME_W')
        pg.locator('#cvHome').scroll_into_view_if_needed(); bb = pg.locator('#cvHome').bounding_box()
        pg.mouse.click(bb['x'] + (h['x0'] + h['x1']) / 2 * bb['width'] / W, bb['y'] + (h['y0'] + h['y1']) / 2 * bb['height'] / 420); pg.wait_for_timeout(200)
    chk('home: a MISSION CONTROL hit area exists and sits clear of the other hit areas except where they already overlap', ev("HOMEHIT.some(h=>h.id==='mission')") and ev("(()=>{const m=HOMEHIT.find(h=>h.id==='mission');return HOMEHIT.filter(h=>h.id!=='mission').every(h=>m.x0>=h.x1||m.x1<=h.x0||m.y0>=h.y1||m.y1<=h.y0)})()"))
    was = ev("DB.user"); ev("DB.user={name:'Sam',cls:'7B'}")
    home_tap('mission'); chk('home: Mission Control is locked until Part 4 is done, and says so', 'Mission Control opens when you finish Part 4 in the Workshop.' in pg.locator('#toast').inner_text() and ev("VIEW") == 'vHome', pg.locator('#toast').inner_text())
    pg.evaluate("__fhq.dbSet('stamps',{c6d:1})"); home_tap('mission'); pg.wait_for_timeout(300)
    chk('home: Mission Control opens Part 5 once Part 4 is done', ev("CH&&CH.id") == 'c6e' and ev("VIEW") == 'vChapter')
    if ev("!!$('#modal') && !$('#modal').hidden"): ev('closeModal()')
    ev("show('vHome')"); pg.evaluate("__fhq.dbSet('stamps',{})"); ev("DB.user=%s" % json.dumps(was)); ev("renderHome()"); pg.wait_for_timeout(200)
    chk('home: Chapter 6 is on the chapter list with Part 1 and Part 2 tiles', pg.locator('#chapterCards [data-open=c6a]').count() == 1 and pg.locator('#chapterCards [data-open=c6b]').count() == 1)
    pg.locator('#workshopCard [data-open=c6a]').click(); pg.wait_for_timeout(2900)
    chk('first open: the live call from GASA Mission Control shows', pg.locator('#modal .txmodal').is_visible() and 'Incoming call · GASA Mission Control' in pg.locator('#modal').inner_text() and 'Live from the Gumdrop · Planet Glimmer-9' in pg.locator('#modal').inner_text())
    chk('transmission: Smooshy is safe inside, the 60 N limit and the Workshop training are stated', "I'm safe inside" in pg.locator('#modal').inner_text() and '60 N' in pg.locator('#modal').inner_text() and 'train on the simulator in the Workshop' in pg.locator('#modal').inner_text())
    chk('no black box anywhere on the page, in the source or in the modal', 'lack box' not in pg.locator('#modal').inner_text() and 'lack box' not in open('dist/test.html').read() and 'trapped' not in pg.locator('#modal').inner_text())
    pg.screenshot(path=OUT + 'transmission.png')
    pg.locator('#txAgain').click(); pg.wait_for_timeout(300); chk('transmission: the crash can be replayed', pg.locator('#cvTx').is_visible())
    pg.locator('#txGo').click(); pg.wait_for_timeout(200)
    chk('transmission: after accepting, the five parts are listed and the brief says GASA', pg.locator('#modal .txlist li').count() == 5 and '5 jobs stand between GASA and a happy gummy bear' in pg.locator('#modal').inner_text(), pg.locator('#modal').inner_text()[:200])
    pg.locator('#modal [data-close]').first.click(); pg.wait_for_timeout(200)
    chk('the briefing is remembered', ev("dbGet('ws.briefed')") is True)
    chk('the Rescue board is on the chapter page with 6 slots', pg.locator('#rescueBoard').is_visible() and pg.locator('#rescueBoard .rbslots li').count() == 6)
    chk('the board says what is next', pg.locator('#rescueBoard .rbnext').inner_text() == 'Next: Part 1 trains you on the lever in the simulator.', pg.locator('#rescueBoard .rbnext').inner_text())
    chk('the board has the new slot titles and no toolkit pictures or beacon', ev("RB_SLOTS.map(s=>s.title).join('|')") == 'Lever training|Toolkit training|Maths check ready|Route training|Smooshy saved!|Gummy Base One built' and not pg.locator('#rescueBoard img').count())
    chk('every slot is a button; slots for Parts that exist open them', pg.locator('#rescueBoard .rbslots button.rbslot').count() == 6 and all(ev("!!secOf('%s')" % k) == (pg.locator('#rescueBoard [data-open=%s]' % k).count() == 1) for k in ['c6a', 'c6b', 'c6c', 'c6d', 'c6e', 'c6f']))
    for k in ['c6b', 'c6e', 'c6a']:
        pg.locator('#rescueBoard [data-open=%s]' % k).click(); pg.wait_for_timeout(250)
        if ev("!!$('#modal') && !$('#modal').hidden"): ev('closeModal()')
        chk('Rescue board: the %s slot opens its Part' % k, ev("CH.id") == k, ev("CH.id"))
    ev("(()=>{window.__x=SECTIONS.splice(SECTIONS.findIndex(s=>s.id==='c6f'),1)[0];renderRescue();})()")
    chk('a Part that is not open yet is a disabled "coming soon" slot', pg.locator('#rescueBoard .rbslots li').nth(5).locator('button').is_disabled() and 'coming soon' in pg.locator('#rescueBoard .rbslots li').nth(5).inner_text())
    ev("(()=>{SECTIONS.push(window.__x);renderRescue();})()")
    pg.screenshot(path=OUT + 'board.png')

    # ================= lv1: too heavy, meet the lever =================
    cards(); dock(); ev("qPlace('hidden')"); pg.wait_for_timeout(200); pg.screenshot(path=OUT + 'lv1_start.png')
    chk('lv1: just a rope to start, the lever waits in the tray; no rulers yet and no old panels', pg.locator('#lsTray [data-lsadd=lever]').count() == 1 and ev("WS.mach") == 'hand' and not ev("LAB.show.has('rulers')") and not pg.locator('#wsMachs').is_visible())
