    q('q5').locator('[data-o="0"]').first.click(); pg.wait_for_timeout(100); chk('lv3 q5: the big rule (key idea)', ptsq('q5').startswith('1 of 1') and 'bigger distance' in q('q5').inner_text(), ptsq('q5'))
    finish('lv3')

